73	  };
74	
75	  const handleCopySecret = (secret: string) => {
76	    copy(secret);
77	    setSecretCopied(true);
78	    setTimeout(() => setSecretCopied(false), 2000);
79	  };
80	
81	  const handleRevealSecret = async () => {
82	    if (!webhookName) return;
83	    try {
84	      secretState.setLoading();
85	      const { signingSecret } = await userServiceClient.getUserWebhookSigningSecret({ name: webhookName });
86	      setRevealedSecret(signingSecret);
