93	  // Lets a pre-existing webhook that has no secret adopt one. The secret is
94	  // persisted immediately and revealed so the user can copy it once.
95	  const handleGenerateSecret = async () => {
96	    if (!webhookName) return;
97	    const bytes = crypto.getRandomValues(new Uint8Array(32));
98	    const secret = "whsec_" + btoa(String.fromCharCode(...bytes));
99	    try {
100	      secretState.setLoading();
101	      await userServiceClient.updateUserWebhook({
102	        webhook: { name: webhookName, signingSecret: secret },
103	        updateMask: create(FieldMaskSchema, { paths: ["signing_secret"] }),
104	      });
105	      setHasExistingSecret(true);
106	      setRevealedSecret(secret);
107	      handleCopySecret(secret);
108	      secretState.setFinish();
109	    } catch (error: unknown) {
110	      handleError(error, toast.error, { context: "Generate signing secret", onError: () => secretState.setError() });
111	    }
112	  };
113	
114	  // When closing after a successful create, refresh the parent list regardless of how the dialog is dismissed.
115	  const handleOpenChange = (next: boolean) => {
